def write_file(root: Path, relative: str) -> None:
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("placeholder\n", encoding="utf-8")


class ActiveWorkspaceLayoutTests(unittest.TestCase):
    def test_setup_tracks_bindgen_generator_without_active_sys_package(self) -> None:
        removed_sys_member = "windows" + "-sys"
        removed_sys_module = "windows" + "_sys"

        self.assertIn("windows_bindgen", setup.ACTIVE_WORKSPACE_MEMBERS)
        self.assertNotIn(removed_sys_member, setup.ACTIVE_WORKSPACE_MEMBERS)
        self.assertIn("windows_bindgen", setup.PACKAGE_DEPENDENCIES)
        self.assertNotIn(removed_sys_module, setup.PACKAGE_DEPENDENCIES)
        self.assertNotIn("windows_bindgen", setup.REFERENCE_ONLY_PACKAGES)
        self.assertEqual(setup.GENERATED_MANIFEST_HEADER, "Generated by windows_bindgen. DO NOT EDIT.")
        self.assertEqual(codegen.GENERATOR_BINARY.name, "windows_bindgen.exe")

    def test_script_audits_read_active_members_from_workspace_manifest(self) -> None:
        with tempfile.TemporaryDirectory() as temp_dir:
            workspace = Path(temp_dir)
            (workspace / "cjpm.toml").write_text(
                "[workspace]\nmembers = [\"windows_bindgen\"]\n",
                encoding="utf-8",
            )

            self.assertEqual(ignored.workspace_members(workspace), ["windows_bindgen"])
            self.assertEqual(abi.workspace_members(workspace), ["windows_bindgen"])


class WorkspaceTestContractTests(unittest.TestCase):
    def write_text(self, root: Path, relative: str, text: str = "placeholder\n") -> Path:
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        return path

    def assert_contract_fail(self, workspace: Path, expected: str) -> None:
        with self.assertRaises(contracts.WorkspaceTestContractViolation) as raised:
            contracts.check_test_only_sources_stay_in_test_files(workspace)
        self.assertIn(expected, str(raised.exception))

    def test_rejects_test_support_names_in_production_sources(self) -> None:
        cases = [
            "windows_collections/src/test_support.cj",
            "windows_collections/src/collection_test_support.cj",
        ]
        for relative in cases:
            with self.subTest(relative=relative):
                with tempfile.TemporaryDirectory() as temp_dir:
                    workspace = Path(temp_dir) / "workspace"
                    self.write_text(workspace, relative, "package windows_collections\nfunc supportHelper() {}\n")

                    self.assert_contract_fail(workspace, "must be named *_support_test.cj")

    def test_rejects_unittest_markers_in_non_test_sources(self) -> None:
        cases = [
            ("windows_core/src/production_import.cj", "package windows_core\nimport std.unittest.*\n"),
            ("windows_core/src/production_annotation.cj", "package windows_core\n@Test\nfunc accidentalTest() {}\n"),
        ]
        for relative, text in cases:
            with self.subTest(relative=relative):
                with tempfile.TemporaryDirectory() as temp_dir:
                    workspace = Path(temp_dir) / "workspace"
                    self.write_text(workspace, relative, text)

                    self.assert_contract_fail(workspace, "does not end with _test.cj")

    def test_allows_support_test_sources(self) -> None:
        with tempfile.TemporaryDirectory() as temp_dir:
            workspace = Path(temp_dir) / "workspace"
            self.write_text(
                workspace,
                "windows_collections/src/collection_support_test.cj",
                "package windows_collections\nimport std.unittest.*\n@Test\nfunc supportSmoke() {}\n",
            )

            contracts.check_test_only_sources_stay_in_test_files(workspace)


class ActiveToolGateTests(unittest.TestCase):
    def write_text(self, root: Path, relative: str, text: str = "placeholder\n") -> Path:
        path = root / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")
        return path

    def runtime_smoke_text(self) -> str:
        return (
            "func testRealActivationFactoryReportsUnavailableClass() {\n"
            "    match (windows_core.activationFactory<MissingActivationFactorySmokeClass>()) {\n"
            "        case Result<IActivationFactory>.Err(error) => @Expect(error.code(), REGDB_E_CLASSNOTREG)\n"
            "        case _ => ()\n"
            "    }\n"
            "}\n"
            "func testRealPropertyValueInt32ArrayRoundTrip() {\n"
            "    let boxed = unsafe { PropertyValue.CreateInt32Array([1i32]) }\n"
            "    let values = unsafe { boxed.GetInt32Array() }\n"
            "}\n"
            "func testRealUriDecoderRoundTripsHStringAndCollectionProjection() {\n"
            "    let uri = unsafe { Uri.CreateUri(text) }\n"
            "    let decoder = unsafe { uri.QueryParsed() }\n"
            "    let value = unsafe { decoder.GetFirstValueByName(key) }\n"
            "    let first = unsafe { decoder.GetAt(0u32) }\n"
            "}\n"
        )

    def collections_smoke_text(self) -> str:
        return (
            "func testStockInt32VectorViewRoundTripsThroughProjection() {\n"
            "    let view = toVectorView(ArrayList<Int32>([10i32, 20i32, 30i32]))\n"
            "    @Expect(unsafe { view.Size() }, 3u32)\n"
            "    @Expect(unsafe { view.GetAt(0u32) }, 10i32)\n"
            "    var foundIndex = 99u32\n"
            "    @Expect(unsafe { view.IndexOf(20i32, CPointer<UInt32>(inout foundIndex)) }, true)\n"
            "}\n"
        )

    def future_smoke_text(self) -> str:
        return (
            "func testReadyOperationProjectsCompletedResult() {\n"
            "    let operation = IAsyncOperation<Int32>.ready(42i32)\n"
            "    let info = operation.asIAsyncInfo()\n"
            "    @Expect(unsafe { info.Status() } == AsyncStatus_Completed, true)\n"
            "    match (operation.join()) {\n"
            "        case Result<Int32>.Ok(value) => @Expect(value, 42i32)\n"
            "        case _ => ()\n"
            "    }\n"
            "}\n"
            "func testSpawnedActionPropagatesWindowsExceptionThroughJoin() {\n"
            "    let action = IAsyncAction.spawnAsync({ => throw WindowsException(E_POINTER) })\n"
            "    let info = action.asIAsyncInfo()\n"
            "    match (action.join()) {\n"
            "        case Result<Unit>.Err(error) => @Expect(error.code(), E_POINTER)\n"
            "        case _ => ()\n"
            "    }\n"
            "    @Expect(unsafe { info.Status() } == AsyncStatus_Error, true)\n"
            "}\n"
        )

    def write_active_tools_workspace(
        self,
        workspace: Path,
        *,
        runtime_runner_text: str | None = None,
        runtime_smoke_text: str | None = None,
        macro_check_text: str | None = None,
    ) -> None:
        self.write_text(workspace, "windows_bindgen/src/main.cj", "writer.fileHashes()\nfile_hashes\n")
        self.write_text(workspace, "windows_bindgen/src/json_loader.cj")
        self.write_text(workspace, "windows_bindgen/src/winmd_adapter.cj")
        self.write_text(workspace, "windows_winui3/src/xaml/mod.cj")
        self.write_text(
            workspace,
            "scripts/run_windows_runtime_tests.py",
            runtime_runner_text
            if runtime_runner_text is not None
            else (
                "import argparse\n"
                "from pathlib import Path\n"
                "SPLIT_PACKAGES = ('windows_foundation', 'windows_collections', 'windows_future')\n"
                "BINARY = Path('windows_foundation.exe')\n"
                "PACKAGE = Path('.')\n"
                "ROOT = Path('.')\n"
                "def package_binary(package):\n"
                "    return Path(package.replace('-', '_') + '.exe')\n"
                "def run_with_watchdog(command, *, cwd, env, timeout_seconds):\n"
                "    return 0, 'PASSED: 1 FAILED: 0 ERROR: 0'\n"
                "def summary_counts(output):\n"
                "    return {'PASSED': 1, 'FAILED': 0, 'ERROR': 0}\n"
                "def remove_expected_runtime_binary(binary=BINARY):\n"
                "    marker = '$test.cjo.flag'\n"
                "def runtime_test_command(binary, filter_value, extra_args):\n"
                "    # do not pass --timeout-each\n"
                "    return ['cjv', 'exec', str(binary), '--no-color', '--progress-brief']\n"
                "def main():\n"
                "    parser = argparse.ArgumentParser()\n"
                "    parser.add_argument('--package', choices=SPLIT_PACKAGES, default='windows_foundation')\n"
                "    args = parser.parse_args()\n"
                "    binary = package_binary(args.package)\n"
                "    env = {'cjHeapSize': '32GB'}\n"
                "    remove_expected_runtime_binary(binary)\n"
                "    run_with_watchdog(['cjpm', 'test', '--no-run'], cwd=PACKAGE, env=env, timeout_seconds=1)\n"
                "    command = runtime_test_command(binary, None, [])\n"
                "    return run_with_watchdog(command, cwd=ROOT, env=env, timeout_seconds=1)\n"
            ),
        )
        self.write_text(
            workspace,
            "scripts/run_windows_workspace_tests.py",
            '"cjv", "exec"\n--no-run\ncjHeapSize\n32GB\nFAILED\nERROR\nsummary_counts\n'
            "test_package_names\nremove_expected_test_binaries\nworkspace_build_command\nworkspace_test_command\n"
            "--dry-run\n--self-test\n",
        )
        self.write_text(
            workspace,
            "scripts/check_windows_common_codegen.py",
            '--allow-missing-winui-metadata\ncannot silently skip missing WinUI/WindowsAppSDK metadata\n'
            'remove_expected_generator_binary()\nwith_suffix(".cjo")\n',
        )
        self.write_text(
            workspace,
            "scripts/run_windows_quality_gate.py",
            '--allow-missing-winui-metadata\nquick workspace Cangjie tests\n"windows_bindgen"\n"windows_core"\n'
            '"windows_implement"\n"windows_interface"\n"windows_foundation"\n"windows_collections"\n"windows_future"\n'
            'RUNTIME_SMOKE_FILTERS_BY_PACKAGE\nf"{package} smoke test"\n"--package"\n'
            "testRealActivationFactoryReportsUnavailableClass\n"
            "testRealPropertyValueInt32ArrayRoundTrip\ntestRealUriDecoderRoundTripsHStringAndCollectionProjection\n"
            "testStockInt32VectorViewRoundTripsThroughProjection\n"
            "testReadyOperationProjectsCompletedResult\ntestSpawnedActionPropagatesWindowsExceptionThroughJoin\n"
            "generate_vector_input_abi.py\n--check-all\nmacro fixtures\nwindows_interface/scripts/check_macros.py\n",
        )
        self.write_text(
            workspace,
            "windows_foundation/src/windows_foundation_smoke_test.cj",
            runtime_smoke_text if runtime_smoke_text is not None else self.runtime_smoke_text(),
        )
        self.write_text(
            workspace,
            "windows_collections/src/windows_collections_smoke_test.cj",
            self.collections_smoke_text(),
        )
        self.write_text(
            workspace,
            "windows_future/src/windows_future_smoke_test.cj",
            self.future_smoke_text(),
        )
        self.write_text(
            workspace,
            "windows_interface/scripts/check_macros.py",
            macro_check_text
            if macro_check_text is not None
            else (
                "def cjv_exec_args(executable):\n    return []\n"
                "def compile_descriptor_codegen_fixture(env):\n"
                "    marker = 'descriptor_codegen_compile_fixture'\n"
                "    marker2 = 'windows_core.winrtStoreGenericOut<Fixture_IOutput>(result__, value)'\n"
                "run(cjv_exec_args(fixture_exe), env=env)\n"
            ),
        )

    def assert_active_tools_fail(self, workspace: Path, expected: str) -> None:
        stderr = io.StringIO()
        with contextlib.redirect_stderr(stderr):
            with self.assertRaises(SystemExit) as raised:
                setup.check_active_tools(workspace)
        self.assertEqual(raised.exception.code, 1)
        self.assertIn(expected, stderr.getvalue())

    def test_active_tools_rejects_stubbed_runtime_smoke_body(self) -> None:
        with tempfile.TemporaryDirectory() as temp_dir:
            workspace = Path(temp_dir) / "workspace"
            self.write_active_tools_workspace(
                workspace,
                runtime_smoke_text=(
                    "func testRealActivationFactoryReportsUnavailableClass() { () }\n"
                    "func testRealPropertyValueInt32ArrayRoundTrip() { () }\n"
                    "func testRealUriDecoderRoundTripsHStringAndCollectionProjection() { () }\n"
                ),
            )

            self.assert_active_tools_fail(workspace, "no longer exercises real WinRT calls")

    def test_active_tools_rejects_macro_check_without_descriptor_codegen_compile_fixture(self) -> None:
        with tempfile.TemporaryDirectory() as temp_dir:
            workspace = Path(temp_dir) / "workspace"
            self.write_active_tools_workspace(
                workspace,
                macro_check_text="def cjv_exec_args(executable):\n    return []\nrun(cjv_exec_args(fixture_exe), env=env)\n",
            )

            self.assert_active_tools_fail(workspace, "descriptor_codegen WinRT out-slot output")

