class VtableNoneBranchGateTests(unittest.TestCase):
    def write_vtable_sources(
        self,
        workspace: Path,
        *,
        foundation: str | None = None,
        collections: str | None = None,
        marshaler: str | None = None,
        core_agile: str | None = None,
        core_reference: str | None = None,
        core_descriptor_tests: str | None = None,
        core_weak: str | None = None,
        implement_weak: str | None = None,
        implement_surface: str | None = None,
        implement_composable: str | None = None,
        implement_thunk: str | None = None,
        implement_weak_tests: str | None = None,
        interface_macro: str | None = None,
        interface_macro_fixture: str | None = None,
        bindgen_render: str | None = None,
        bindgen_tests: str | None = None,
        common: str | None = None,
    ) -> None:
        foundation_path = workspace / "windows_foundation" / "src" / "foundation_runtime.cj"
        collections_path = workspace / "windows_collections" / "src" / "collections_runtime.cj"
        # The foundationNoInterface* helper definitions were down-sinked to
        # windows_core; the foundation projection keeps only their call sites.
        winrt_abi_thunks_path = workspace / "windows_core" / "src" / "winrt_abi_thunks.cj"
        marshaler_path = workspace / "windows_core" / "src" / "marshaler.cj"
        core_agile_path = workspace / "windows_core" / "src" / "agile_reference.cj"
        core_reference_path = workspace / "windows_core" / "src" / "weak.cj"
        core_descriptor_test_path = workspace / "windows_core" / "src" / "core_descriptor_test.cj"
        core_weak_path = workspace / "windows_core" / "src" / "weak_ref_count.cj"
        implement_weak_path = workspace / "windows_implement" / "src" / "weak_ref_count.cj"
        implement_surface_path = workspace / "windows_implement" / "src" / "interface_impl_surface.cj"
        implement_composable_path = workspace / "windows_implement" / "src" / "composable_activation.cj"
        implement_thunk_path = workspace / "windows_implement" / "src" / "thunk_builder.cj"
        implement_weak_tests_path = workspace / "windows_implement" / "src" / "weak_ref_count_test.cj"
        interface_macro_path = workspace / "windows_interface" / "src" / "macros" / "windows_interface_macros.cj"
        interface_macro_fixture_path = workspace / "windows_interface" / "tests" / "macros" / "generated_interface_fixture.cj"
        bindgen_render_path = workspace / "windows_bindgen" / "src" / "render_symbol.cj"
        bindgen_tests_path = workspace / "windows_bindgen" / "src" / "main_test.cj"
        common_path = workspace / "windows_common" / "src" / "impl" / "symbols_1.cj"
        foundation_path.parent.mkdir(parents=True, exist_ok=True)
        collections_path.parent.mkdir(parents=True, exist_ok=True)
        winrt_abi_thunks_path.parent.mkdir(parents=True, exist_ok=True)
        marshaler_path.parent.mkdir(parents=True, exist_ok=True)
        core_agile_path.parent.mkdir(parents=True, exist_ok=True)
        core_reference_path.parent.mkdir(parents=True, exist_ok=True)
        core_descriptor_test_path.parent.mkdir(parents=True, exist_ok=True)
        core_weak_path.parent.mkdir(parents=True, exist_ok=True)
        implement_weak_path.parent.mkdir(parents=True, exist_ok=True)
        implement_surface_path.parent.mkdir(parents=True, exist_ok=True)
        implement_composable_path.parent.mkdir(parents=True, exist_ok=True)
        implement_thunk_path.parent.mkdir(parents=True, exist_ok=True)
        implement_weak_tests_path.parent.mkdir(parents=True, exist_ok=True)
