            "                        } catch (error: windows_core.WindowsException) {\n"
            "                            if (result.isNotNull()) {\n"
            "                                unsafe { result.write(CPointer<Unit>()) }\n"
            "                            }\n"
            "                            error.code().value\n"
            "                        } catch (_: Windows_Foundation_Collections_IIterable_1ExceptionBase) {\n"
            "                            if (result.isNotNull()) {\n"
