            "    let ${dataName} = unsafe { ${spec.dataSlotName}.read() }\n"
            "    windows_core.winrtReleaseGenericArrayOut<${spec.elementProjectedType}>(CPointer<Unit>(${dataName}), ${sizeName})\n"
            "    windows_core.coTaskMemFree(CPointer<Unit>(${dataName}))\n"
