class AbiOwnershipAuditTests(unittest.TestCase):
    def write_winui_xaml(self, workspace: Path, text: str) -> None:
        source = workspace / "windows_winui3" / "src" / "xaml" / "mod.cj"
        source.parent.mkdir(parents=True, exist_ok=True)
        source.write_text(text, encoding="utf-8")

    def test_query_interface_raw_wrapped_in_local_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    let leaked = Some(raw)\n"
            "    println(\"after\")\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_discarded_wrapper_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    let _ = Ok(raw)\n"
            "    println(\"after\")\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_tail_wrapper_is_consumed(self) -> None:
        self.assertTrue(abi.query_result_consumed(" Some(descriptor.takeFromAbi(raw)) // tail\n", "raw"))
        self.assertTrue(abi.query_result_consumed(" Result<I>.Ok(raw)\n", "raw"))
        self.assertTrue(abi.query_result_consumed(" owner.close()\n Result<I>.Ok(raw)\n", "raw"))

    def test_query_interface_raw_direct_tail_value_is_consumed(self) -> None:
        self.assertTrue(abi.query_result_consumed(" raw\n", "raw"))

    def test_query_interface_raw_unknown_tail_wrapper_is_not_consumed(self) -> None:
        self.assertFalse(abi.query_result_consumed(" Some(debugWrap(raw))\n", "raw"))

    def test_query_interface_raw_unknown_return_wrapper_is_not_consumed(self) -> None:
        self.assertFalse(abi.query_result_consumed(" return Some(debugWrap(raw))\n", "raw"))
        self.assertFalse(abi.query_result_consumed(" return Ok(debugWrap(raw))\n", "raw"))
        self.assertFalse(abi.query_result_consumed(" return Result<I>.Ok(debugWrap(raw))\n", "raw"))

    def test_query_interface_raw_known_return_wrapper_is_consumed(self) -> None:
        self.assertTrue(abi.query_result_consumed(" return Some(descriptor.takeFromAbi(raw))\n", "raw"))
        self.assertTrue(abi.query_result_consumed(" return Ok(InterfaceHandle<I>.fromAbiTake(raw))\n", "raw"))
        self.assertTrue(abi.query_result_consumed(" return Result<I>.Ok(raw)\n", "raw"))
        self.assertTrue(abi.query_result_consumed(" return InterfaceHandle<I>.fromAbiTake(raw)\n", "raw"))

    def test_query_interface_raw_direct_tail_owned_wrapper_is_consumed(self) -> None:
        self.assertTrue(abi.query_result_consumed(" descriptor.takeFromAbi(raw)\n", "raw"))
        self.assertTrue(abi.query_result_consumed(" InterfaceHandle<I>.fromAbiTake(raw)\n", "raw"))
        self.assertTrue(abi.query_result_consumed(" windows_interface.IUnknown.fromAbiTake(raw)\n", "raw"))

    def test_query_interface_raw_discarded_owned_wrapper_is_not_consumed(self) -> None:
        self.assertFalse(abi.query_result_consumed(" let _ = descriptor.takeFromAbi(raw)\n", "raw"))
        self.assertFalse(abi.query_result_consumed(" let _ = IUnknown.fromAbiTake(raw)\n", "raw"))

    def test_generic_owned_constructor_routes_from_abi_take_to_guard(self) -> None:
        self.assertIsNotNone(abi.OWNED_CONSTRUCTOR_RE.search("OwnedHandler<TResult>(raw)"))

    def test_query_interface_raw_direct_return_is_consumed(self) -> None:
        self.assertTrue(abi.query_result_consumed(" return raw // transfers ownership\n", "raw"))

    def test_query_interface_raw_predicate_return_is_not_consumed(self) -> None:
        self.assertFalse(abi.query_result_consumed(" return raw.isNull()\n", "raw"))

    def test_query_interface_raw_predicate_tail_wrapper_is_not_consumed(self) -> None:
        self.assertFalse(abi.query_result_consumed(" Some(raw.isNull())\n", "raw"))

    def test_query_interface_raw_string_fake_release_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    println(\"raw.close()\")\n"
            "    return None\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_raw_string_fake_release_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    println(#\"descriptor.releasePointer(raw)\"#)\n"
            "    return None\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_block_comment_fake_release_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    /* raw.close() */\n"
            "    return None\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_wrapper_before_statement_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    Some(raw)\n"
            "    println(\"after\")\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_same_line_wrapper_before_statement_is_not_consumed(self) -> None:
        self.assertFalse(abi.query_result_consumed(" Some(raw); println(\"after\")\n", "raw"))
        self.assertFalse(abi.query_result_consumed(" Ok(raw); println(\"after\")\n", "raw"))

    def test_query_interface_raw_explicit_release_is_consumed(self) -> None:
        body = (
            "\n"
            "    let view = descriptor.viewOf(raw)\n"
            "    let _ = descriptor.releasePointer(raw)\n"
            "    view\n"
        )

        self.assertTrue(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_one_branch_release_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    if (shouldRelease) {\n"
            "        let _ = descriptor.releasePointer(raw)\n"
            "    }\n"
            "    println(\"after\")\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_catch_release_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    try { risky() } catch (e: Exception) { raw.close() }\n"
            "    return None\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_lambda_release_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    let cleanup = { => raw.close() }\n"
            "    return None\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_nested_function_release_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    func cleanup(): Unit { raw.close() }\n"
            "    return None\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_finally_release_is_consumed(self) -> None:
        body = (
            "\n"
            "    try { risky() } finally { raw.close() }\n"
            "    return None\n"
        )

        self.assertTrue(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_newline_braced_one_branch_release_is_not_consumed(self) -> None:
        body = (
            "\n"
            "    if (shouldRelease)\n"
            "    {\n"
            "        let _ = descriptor.releasePointer(raw)\n"
            "    }\n"
            "    println(\"after\")\n"
        )

        self.assertFalse(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_nested_match_all_cases_release_is_consumed(self) -> None:
        body = (
            "\n"
            "    match (other()) {\n"
            "        case Some(value) =>\n"
            "            descriptor.releasePointer(raw)\n"
            "            Some(value)\n"
            "        case None =>\n"
            "            descriptor.releasePointer(raw)\n"
            "            None\n"
            "    }\n"
        )

        self.assertTrue(abi.query_result_consumed(body, "raw"))

    def test_query_interface_raw_unconditional_unsafe_release_is_consumed(self) -> None:
        body = (
            "\n"
            "    unsafe {\n"
            "        releasePointer(raw)\n"
            "    }\n"
            "    println(\"after\")\n"
        )

        self.assertTrue(abi.query_result_consumed(body, "raw"))

