class IgnoredResultsAuditTests(unittest.TestCase):
    def test_constructor_receiver_ok_before_outer_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Result<Unit> {",
            "    HRESULT(hr).ok()",
            "    println(\"after\")",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_unsafe_block_receiver_ok_before_outer_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Result<Unit> {",
            "    HRESULT(unsafe { table.RemoveClick(raw, token) }).ok()",
            "    println(\"after\")",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_stored_constructor_receiver_ok_is_allowed(self) -> None:
        lines = [
            "public func ok(): Result<Unit> {",
            "    let result = HRESULT(hr).ok()",
            "    result",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), [])

    def test_discarded_ok_assignment_with_semicolon_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    let _ = hr.ok();",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_typed_discarded_ok_assignment_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    let _: windows_core.Result<Unit> = hr.ok()",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_var_discarded_ok_assignment_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    var _ = hr.ok()",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_parenthesized_discarded_ok_assignment_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    let _ = (hr.ok())",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_discarded_conditional_ok_assignment_is_rejected(self) -> None:
        lines = [
            "public func ok(condition: Bool): Unit {",
            "    let _ = if (condition) { hr.ok() } else { other.ok() }",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_multiline_discarded_ok_assignment_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    let _ =",
            "        hr.ok()",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_multiline_discarded_match_ok_assignment_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    let _ =",
            "        match (value) {",
            "            case Some(_) => hr.ok()",
            "            case None => other.ok()",
            "        }",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_same_line_statement_ok_before_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    hr.ok(); println(\"after\")",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_same_line_ok_before_work_with_block_comment_brace_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    hr.ok() /* { */; println(\"after\")",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_parenthesized_statement_ok_before_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    (hr.ok());",
            "    println(\"after\")",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_same_line_discarded_ok_assignment_before_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    let _ = hr.ok(); println(\"after\")",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_inline_function_body_ok_before_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit { hr.ok(); println(\"after\") }",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:1: ignored Result.ok() value"])

    def test_function_tail_ok_before_next_declaration_is_allowed(self) -> None:
        lines = [
            "public func ok(): Result<Unit> {",
            "    hr.ok()",
            "}",
            "public func other(): Bool {",
            "    true",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), [])

    def test_loop_tail_ok_is_rejected(self) -> None:
        while_lines = [
            "public func ok(): Unit {",
            "    while (condition) {",
            "        hr.ok()",
            "    }",
            "}",
        ]
        self.assertEqual(ignored.scan_lines("<test>", while_lines), ["<test>:3: ignored Result.ok() value"])

        for_lines = [
            "public func ok(): Unit {",
            "    for (item in items) {",
            "        hr.ok()",
            "    }",
            "}",
        ]
        self.assertEqual(ignored.scan_lines("<test>", for_lines), ["<test>:3: ignored Result.ok() value"])

    def test_branch_tail_ok_before_outer_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Result<Unit> {",
            "    if (condition) {",
            "        hr.ok()",
            "    }",
            "    println(\"after\")",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:3: ignored Result.ok() value"])

    def test_inline_if_body_nontail_ok_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    if (condition) { hr.ok(); println(\"after\") }",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_assigned_inline_control_ok_before_lambda_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    let f = { => if (condition) { HRESULT(hr).ok() }; println(\"after\") }",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_assigned_lambda_tail_ok_is_allowed(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    let f = { => HRESULT(hr).ok() }",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), [])

    def test_inline_case_body_nontail_ok_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    match (value) {",
            "        case Some(_) => hr.ok(); println(\"after\")",
            "        case None => other.ok()",
            "    }",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:3: ignored Result.ok() value"])

    def test_single_line_inline_case_body_nontail_ok_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    match (value) { case Some(_) => hr.ok(); println(\"after\") case None => () }",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:2: ignored Result.ok() value"])

    def test_inline_braced_case_body_nontail_ok_is_rejected(self) -> None:
        lines = [
            "public func ok(): Unit {",
            "    match (value) {",
            "        case Some(_) => { hr.ok(); println(\"after\") }",
            "        case None => other.ok()",
            "    }",
            "}",
        ]

        self.assertEqual(ignored.scan_lines("<test>", lines), ["<test>:3: ignored Result.ok() value"])

    def test_try_tail_ok_before_outer_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Result<Unit> {",
            "    try {",
            "        hr.ok()",
            "    } catch (e: Exception) {",
            "        other.ok()",
            "    }",
            "    println(\"after\")",
            "}",
        ]

        self.assertEqual(
            ignored.scan_lines("<test>", lines),
            [
                "<test>:3: ignored Result.ok() value",
                "<test>:5: ignored Result.ok() value",
            ],
        )

    def test_match_arm_tail_ok_before_outer_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Result<Unit> {",
            "    match (value) {",
            "        case Some(_) => {",
            "            hr.ok()",
            "        }",
            "        case None => {",
            "            other.ok()",
            "        }",
            "    }",
            "    println(\"after\")",
            "}",
        ]

        self.assertEqual(
            ignored.scan_lines("<test>", lines),
            [
                "<test>:4: ignored Result.ok() value",
                "<test>:7: ignored Result.ok() value",
            ],
        )

    def test_inline_match_arm_tail_ok_before_outer_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Result<Unit> {",
            "    match (value) {",
            "        case Some(_) => hr.ok()",
            "        case None => other.ok()",
            "    }",
            "    println(\"after\")",
            "}",
        ]

        self.assertEqual(
            ignored.scan_lines("<test>", lines),
            [
                "<test>:3: ignored Result.ok() value",
                "<test>:4: ignored Result.ok() value",
            ],
        )

    def test_inline_if_else_tail_ok_before_outer_work_is_rejected(self) -> None:
        lines = [
            "public func ok(): Result<Unit> {",
            "    if (condition) {",
            "        hr.ok()",
            "    } else { other.ok() }",
            "    println(\"after\")",
            "}",
        ]

        self.assertEqual(
            ignored.scan_lines("<test>", lines),
            [
                "<test>:3: ignored Result.ok() value",
                "<test>:4: ignored Result.ok() value",
            ],
        )


class ShellScriptGateTests(unittest.TestCase):
    def test_rejects_power_shell_batch_and_cmd_scripts(self) -> None:
        with tempfile.TemporaryDirectory() as temp_dir:
            workspace = Path(temp_dir)
            write_file(workspace, "tools/build.ps1")
            write_file(workspace, "tools/build.bat")
            write_file(workspace, "tools/build.cmd")
            write_file(workspace, ".git/ignored.ps1")
            write_file(workspace, "target/ignored.bat")

            stderr = io.StringIO()
            with contextlib.redirect_stderr(stderr):
                with self.assertRaises(SystemExit) as raised:
                    setup.check_no_shell_scripts(workspace)

            self.assertEqual(raised.exception.code, 1)
            message = stderr.getvalue()
            self.assertIn("tools/build.ps1", message)
            self.assertIn("tools/build.bat", message)
            self.assertIn("tools/build.cmd", message)
            self.assertNotIn("ignored.ps1", message)
            self.assertNotIn("ignored.bat", message)


class WinuiXamlHelperGateTests(unittest.TestCase):
    def write_xaml_helper(self, workspace: Path, text: str) -> None:
        path = workspace / "windows_winui3" / "src" / "xaml" / "mod.cj"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text, encoding="utf-8")

    def callback_com_helper_text(
        self,
        *,
        omit_add_ref: bool = False,
        omit_clear_slot: bool = False,
        omit_e_pointer_clear: bool = False,
        unguarded_e_pointer_clear: bool = False,
        omit_windows_exception_catch: bool = False,
        generic_exception_catch_first: bool = False,
        plain_check_hresult: bool = False,
    ) -> str:
        def callback(prefix: str, iid_name: str, clear_slot: str) -> str:
            add_ref_line = "" if omit_add_ref and prefix == "applicationInitializationCallback" else f"    unsafe {{ {prefix}AddRef(thisPtr) }}\n"
            clear_slot_line = "" if omit_clear_slot and prefix == "routedEventHandler" else f"            {clear_slot}(value.slot)\n"
            if omit_e_pointer_clear and prefix == "applicationInitializationCallback":
                e_pointer_clear_line = ""
            elif unguarded_e_pointer_clear and prefix == "applicationInitializationCallback":
                e_pointer_clear_line = "        unsafe { result.write(CPointer<Unit>()) }\n"
            else:
                e_pointer_clear_line = (
                    "        if (result.isNotNull()) {\n"
                    "            unsafe { result.write(CPointer<Unit>()) }\n"
                    "        }\n"
                )
            windows_exception_catch = (
                "    } catch (error: WindowsException) {\n"
                "        return error.code().value\n"
            )
            generic_exception_catch = (
                "    } catch (err: Exception) {\n"
                "        return E_FAIL.value\n"
                "    }\n"
            )
            if omit_windows_exception_catch and prefix == "applicationInitializationCallback":
                catch_lines = generic_exception_catch
            elif generic_exception_catch_first and prefix == "applicationInitializationCallback":
                catch_lines = generic_exception_catch + windows_exception_catch
            else:
                catch_lines = windows_exception_catch + generic_exception_catch
            return (
                f"func {prefix}QueryInterface(thisPtr: CPointer<Unit>, iidPtr: CPointer<GUID>, result: CPointer<CPointer<Unit>>): Int32 {{\n"
                "    if (thisPtr.isNull() || iidPtr.isNull() || result.isNull()) {\n"
                f"{e_pointer_clear_line}"
                "        return E_POINTER.value\n"
                "    }\n"
                "    let iid = unsafe { iidPtr.read() }\n"
                f"    if (iid == IID_IUNKNOWN || iid == {iid_name}) {{\n"
                "        unsafe { result.write(thisPtr) }\n"
                f"{add_ref_line}"
                "        return S_OK.value\n"
                "    }\n"
                "    unsafe { result.write(CPointer<Unit>()) }\n"
                "    return E_NOINTERFACE.value\n"
                "}\n"
                f"func {prefix}AddRef(thisPtr: CPointer<Unit>): UInt32 {{ 1u32 }}\n"
                f"func {prefix}Release(thisPtr: CPointer<Unit>): UInt32 {{\n"
                "    let obj = CPointer<Object>(thisPtr)\n"
                "    var value = unsafe { obj.read() }\n"
                "    if (value.refCount == 0u32) {\n"
                "        return 0u32\n"
                "    }\n"
                "    value.refCount -= 1u32\n"
                "    let refCount = value.refCount\n"
                "    if (refCount == 0u32) {\n"
                "        if (value.slot >= 0) {\n"
                f"{clear_slot_line}"
                "            value.slot = -1\n"
                "        }\n"
                "        unsafe { obj.write(value) }\n"
                "        coTaskMemFree(thisPtr)\n"
                "        return 0u32\n"
                "    }\n"
                "    unsafe { obj.write(value) }\n"
                "    return refCount\n"
                "}\n"
                f"func {prefix}Invoke(): Int32 {{\n"
                "    try {\n"
                "        return S_OK.value\n"
                f"{catch_lines}"
                "}\n"
                f"func {prefix}Vtbl(): Unit {{}}\n"
            )

        check_hresult = (
            "func checkHRESULT(hr: HRESULT, operation: String): Unit {\n"
            "    if (hr.failed()) {\n"
            + (
                "        throw Exception(\"failed\")\n"
                if plain_check_hresult
                else "        throw WindowsException(hr)\n"
            )
            + "    }\n"
            "}\n"
            "func expectFactory(): Unit {}\n"
        )
        default_vtables = (
            "struct ButtonBaseVtbl {\n"
            "    public var AddClick: CFunc<(CPointer<Unit>, CPointer<Unit>, CPointer<EventRegistrationToken>) -> Int32> = { _, _, result =>\n"
            "        if (result.isNotNull()) {\n"
            "            unsafe { result.write(0) }\n"
            "        }\n"
            "        E_NOTIMPL.value\n"
            "    }\n"
            "}\n"
            "struct WindowVtbl {}\n"
            "struct RoutedEventHandlerVtbl {\n"
            "    public var QueryInterface: CFunc<(CPointer<Unit>, CPointer<GUID>, CPointer<CPointer<Unit>>) -> Int32> = { _, _, result =>\n"
            "        if (result.isNotNull()) {\n"
            "            unsafe { result.write(CPointer<Unit>()) }\n"
            "        }\n"
            "        E_NOTIMPL.value\n"
            "    }\n"
            "}\n"
            "struct RoutedEventHandlerObject {}\n"
        )
        return (
            default_vtables
            + check_hresult
            + callback(
                "applicationInitializationCallback",
                "IID_APPLICATION_INITIALIZATION_CALLBACK",
                "clearApplicationInitializationCallbackSlot",
            )
            + callback("routedEventHandler", "IID_ROUTED_EVENT_HANDLER", "clearRoutedEventHandlerSlot")
        )

